<?php
namespace App\Console\Commands;
use App\Mail\BackupCompletedMail; use App\Models\{Organization,User}; use App\Services\{DatabaseBackupService,MailDeliveryService}; use Illuminate\Console\Command;
class RunScheduledBackups extends Command { protected $signature='backups:run-scheduled'; protected $description='Create due automatic database backups'; public function handle(DatabaseBackupService $service,MailDeliveryService $mailer):int {Organization::query()->where('is_active',true)->each(function($org)use($service,$mailer){$settings=data_get($org->settings,'backup',[]);if(!($settings['automatic']??false))return;$last=data_get($settings,'last_auto_backup_at');$frequency=$settings['frequency']??'weekly';$due=!$last||match($frequency){'daily'=>now()->diffInHours($last)>=23,'monthly'=>now()->diffInDays($last)>=28,default=>now()->diffInDays($last)>=6};if(!$due)return;try{$backup=$service->create($org,null,(bool)($settings['include_uploads']??true));if((bool)($settings['email_copy']??false)){$recipient=User::query()->where('organization_id',$org->id)->where('is_active',true)->whereNotNull('email')->whereHas('roles.permissions',fn($query)=>$query->where('name','users.manage'))->orderBy('id')->first();if($recipient){try{$mailer->send($org,$recipient->email,$recipient->name,new BackupCompletedMail($backup,$org));}catch(\Throwable $e){report($e);$this->warn("{$org->name}: backup email could not be delivered");}}}$all=$org->settings??[];$all['backup']['last_auto_backup_at']=now()->toIso8601String();$org->update(['settings'=>$all]);$this->info("Backed up {$org->name}");}catch(\Throwable $e){report($e);$this->error("{$org->name}: {$e->getMessage()}");}});return self::SUCCESS;} }
